package service

import (
	_ "embed"
	"encoding/json"
	"math"
	"stray-kitty/server/internal/domain"
)

// Generated byte-for-byte from the locked v07 geometry by content:sync.
//
//go:embed warehouse_geometry.json
var warehouseGeometryJSON []byte

type warehouseAnchor struct {
	ID                string `json:"id"`
	X, Y              float64
	Floor, Kind, Type string
	R                 float64 `json:"r"`
}

var warehouseSpatial = func() struct {
	Interactions, RandomZones []warehouseAnchor
	EventPoolRandom           []string
} {
	var result struct {
		Interactions, RandomZones []warehouseAnchor
		EventPoolRandom           []string
	}
	if err := json.Unmarshal(warehouseGeometryJSON, &result); err != nil {
		panic(err)
	}
	return result
}()

func warehouseUnlocked(s *domain.GameState) bool {
	return domain.Contains(s.Flags, "tunnel_explored") && domain.Contains(s.Flags, "cats_rescued_batch1") && s.Inventory["clue"] >= 3
}
func nearWarehouse(point *domain.WorldPoint, x, y, radius float64) bool {
	return point != nil && !math.IsNaN(point.X) && !math.IsNaN(point.Y) && !math.IsInf(point.X, 0) && !math.IsInf(point.Y, 0) && math.Hypot(point.X-x, point.Y-y) <= radius
}
func (g *Game) warehouseInteract(s *domain.GameState, c domain.Command) error {
	for _, anchor := range warehouseSpatial.Interactions {
		if anchor.ID != c.InteractionID {
			continue
		}
		if c.Layer != anchor.Floor || !nearWarehouse(c.Position, anchor.X, anchor.Y, 64) {
			return domain.Fail("INTERACTION_WRONG_FLOOR", "请靠近正确楼层的交互标记", 409)
		}
		if anchor.Kind == "light" {
			// All three controllable lamps toggle, as requested during manual QA.
			if domain.Contains(s.Flags, anchor.ID) {
				flags := []string{}
				for _, flag := range s.Flags {
					if flag != anchor.ID {
						flags = append(flags, flag)
					}
				}
				s.Flags = flags
				s.LastResult = domain.Result{Message: "灯光已关闭。"}
			} else {
				s.Flags = domain.Add(s.Flags, anchor.ID)
				s.LastResult = domain.Result{Message: "灯光已亮起。"}
			}
			return nil
		}
		switch anchor.ID {
		case "finale_boss":
			if !warehouseUnlocked(s) || domain.Contains(s.Flags, "finale_boss_victory") {
				return domain.Fail("STAGE_LOCKED", "终章前置不足，或仓库防线已经守住", 409)
			}
			s.Phase = "dialogue"
			s.StoryNodeID = "finale_intro_5"
			s.ChapterID = "finale"
			s.LastResult = domain.Result{Message: "伙伴已经集结，一起守住仓库的归路。"}
			return nil
		case "bunker_exit":
			if !domain.Contains(s.Flags, "finale_boss_victory") {
				return domain.Fail("EXIT_LOCKED", "先守住仓库防线，再打开隔间出口", 409)
			}
			s.Phase = "dialogue"
			s.MapID = "greenhouse"
			s.StoryNodeID = "finale_intro_7"
			s.ChapterID = "finale"
			return nil
		}
		if anchor.Kind == "fixed_event" {
			for _, m := range g.Catalog.Maps {
				if m.ID != "warehouse" {
					continue
				}
				for _, item := range m.Interactions {
					if item.ID != anchor.ID {
						continue
					}
					if domain.Contains(s.DrawnEvents, "node:"+item.EventID) {
						return domain.Fail("ALREADY_COMPLETED", "这里已经调查过了", 409)
					}
					s.Phase = "event"
					s.PendingEventID = item.EventID
					s.PendingEventSource = "node"
					return nil
				}
			}
		}
		return domain.Fail("INVALID_COMMAND", "仓库交互无效", 400)
	}
	return domain.Fail("INVALID_COMMAND", "仓库交互无效", 400)
}

func (g *Game) warehouseRandomZone(s *domain.GameState, id, floor string, point *domain.WorldPoint) error {
	for _, zone := range warehouseSpatial.RandomZones {
		if zone.ID != id {
			continue
		}
		if floor != zone.Floor || !nearWarehouse(point, zone.X, zone.Y, zone.R) {
			return domain.Fail("INVALID_COMMAND", "仓库随机区域位置或楼层无效", 400)
		}
		// Only actual cards consume the persistent deck. Older zone-attempt
		// records are ignored so a missed roll cannot exhaust a location.
		event, triggered, repeatable, err := g.drawRandomEventWithChance(*s, g.RainyZoneChance)
		if err != nil {
			return err
		}
		if !triggered {
			return nil
		}
		s.Phase = "event"
		s.PendingEventID = event
		s.PendingEventSource = "random"
		if !repeatable {
			s.DrawnEvents = domain.Add(s.DrawnEvents, drawnKey(s.MapID, event))
		}
		s.LastResult = domain.Result{Message: "货架后的阴影里传来一阵动静。"}
		return nil
	}
	return domain.Fail("INVALID_COMMAND", "仓库随机区域无效", 400)
}
